UPDATE accounts
SET
    kb_account_id = #{kbAccountId},
    account_name = #{accountName}
WHERE account_id = #{accountId}

UPDATE accounts
SET account_status = #{accountStatus}
WHERE account_id = #{accountId}

UPDATE accounts
SET synced_at = CURRENT_TIMESTAMP
WHERE account_id = #{accountId}
  AND user_id = #{userId}
